{
  "totalMarks": 2,
  "steps": [
    {
      "stepNumber": 1,
      "description": "Expressing 12 and 18 as products of prime factors",
      "working": "Prime factorisation of 12 and 18:\n12 = 2 × 2 × 3 = 2² × 3\n18 = 2 × 3 × 3 = 2 × 3²",
      "marks": 0.5
    },
    {
      "stepNumber": 2,
      "description": "Finding LCM of 12 and 18",
      "working": "LCM(12, 18) = Product of the greatest power of each prime factor involved in the numbers\nLCM(12, 18) = 2² × 3² = 4 × 9 = 36",
      "marks": 0.5
    },
    {
      "stepNumber": 3,
      "description": "Prime factorisation of 20 and 30 and finding their LCM",
      "working": "Prime factorisation of 20 and 30:\n20 = 2 × 2 × 5 = 2² × 5\n30 = 2 × 3 × 5 = 2 × 3 × 5\n\nLCM(20, 30) = 2² × 3 × 5 = 4 × 3 × 5 = 60",
      "marks": 1.0
    }
  ],
  "commonMistakes": [
    "Writing only the final LCM value directly without showing the prime factorisation steps, leading to deduction of ½ mark per sub-part.",
    "Confusing LCM with HCF by taking the smallest powers instead of the highest powers of prime factors (e.g., writing LCM = 2 × 3 = 6 for 12 and 18).",
    "Missing a non-common factor like '3' while computing LCM(20, 30) and writing 2² × 5 = 20."
  ],
  "examTip": "CBSE awards ½ mark strictly for expressing the numbers in exponential prime factor form (e.g., 2² × 3) and ½ mark for the final computed LCM; always show both explicitly."
}
